import heapq

def maximum_product(nums):
    max_heap = []
    min_heap = []

    for num in nums:
        if len(max_heap) < 3:
            heapq.heappush(max_heap, num)
        else:
            if num > max_heap[0]:
                heapq.heappop(max_heap)
                heapq.heappush(max_heap, num)

        if len(min_heap) < 2:
            heapq.heappush(min_heap, -num)
        else:
            if num < -min_heap[0]:
                heapq.heappop(min_heap)
                heapq.heappush(min_heap, -num)

    max_product = max_heap[0] * max_heap[1] * max_heap[2]
    min_product = (-min_heap[0]) * (-min_heap[1]) * max_heap[0]

    return max(max_product, min_product)
[Done]

