def pancake_sort(arr):
    def flip(arr, k):
        return arr[:k][::-1] + arr[k:]

    n = len(arr)
    while n > 1:
        max_index = arr.index(max(arr[:n]))
        if max_index == n - 1:
            n -= 1
            continue
        if max_index!= 0:
            arr = flip(arr, max_index + 1)
        arr = flip(arr, n)
        n -= 1
    return arr
