def min_sum_path(triangle):
    n = len(triangle)
    dp = [[0]*len(row) for row in triangle]
    dp[0][0] = triangle[0][0]
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + triangle[i][0]
        dp[i][-1] = dp[i-1][-1] + triangle[i][-1]
        for j in range(1, len(triangle[i])-1):
            dp[i][j] = triangle[i][j] + min(dp[i-1][j-1], dp[i-1][j])
    return min(dp[-1])
