def is_prime(num: int) -> bool:
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def generate_fibonacci():
    a, b = 0, 1
    while True:
        yield b
        a, b = b, a + b

def prime_fib(n: int) -> int:
    fib_gen = generate_fibonacci()
    count = 0
    while True:
        fib_num = next(fib_gen)
        if is_prime(fib_num):
            count += 1
            if count == n:
                return fib_num
